6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
14:   static const String _base = 'USD';
15:   static const int _pageSize = 20;
16: 
17:   final ValueNotifier<String> _searchQueryNotifier = ValueNotifier('');
18: 
19:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
20: 
21:   late final AnimationController _fadeController;
22: 
23:   late Future<List<CurrencyModel>> _currencyListFuture;
24: 
25:   List<CurrencyModel> _allCurrencies = [];
26: 
27:   int _nextPage = 0;
28: 
29:   bool _hasMore = false;
30: 
31:   bool _isLoadingMore = false;
32: 
33:   @override
34:   void initState() {
35:     super.initState();
36:     _initAnimation();
37:     _initData();
38:   }
39: 
40:   @override
41:   void dispose() {
42:     _searchQueryNotifier.dispose();
43:     _filteredCurrenciesNotifier.dispose();
44:     _fadeController.dispose();
45:     super.dispose();
46:   }
47: 
48:   void _initAnimation() {
49:     _fadeController = AnimationController(
50:       duration: Duration(milliseconds: 400),
51:       vsync: this,
52:     );
53:   }
54: 
55:   void _initData() {
56:     final currencyRepository = context.read<CurrencyRepository>();
57: 
58:     _currencyListFuture = currencyRepository.fetchRates(const CurrencyPageRequest(base: _base, pageSize: _pageSize)).then((CurrencyPage page) {
59:       final List<CurrencyModel> value = page.items;
60:       _allCurrencies = value;
61:       _filteredCurrenciesNotifier = ValueNotifier(value);
62:       _nextPage = page.page + 1;
63:       _hasMore = page.hasMore;
64: 
65:       _fadeController.forward(); // запускаем анимацию
66: 
67:       currencyRepository.saveCurrencyList(value);
68: 
69:       return value;
70:     });
71:   }
72: 
73:   Future<void> _loadNextPage() async {
74:     if (_isLoadingMore || !_hasMore) return;
75: 
76:     setState(() => _isLoadingMore = true);
77: 
78:     final currencyRepository = context.read<CurrencyRepository>();
79: 
80:     try {
81:       final CurrencyPage page = await currencyRepository.fetchRates(
82:         CurrencyPageRequest(base: _base, page: _nextPage, pageSize: _pageSize),
83:       );
84:       if (!mounted) return;
85: 
86:       _allCurrencies = [..._allCurrencies, ...page.items];
87:       _nextPage = page.page + 1;
88:       _hasMore = page.hasMore;
89: 
90:       _filterCurrencies(_searchQueryNotifier.value);
91:     } finally {
92:       if (mounted) {
93:         setState(() => _isLoadingMore = false);
94:       }
95:     }
96:   }
97: 
98:   void _filterCurrencies(String query) {
99:     _searchQueryNotifier.value = query;
100: 
101:     final String lowerQuery = query.toLowerCase();
102:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
103:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
104:     });
105: 
106:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
107:   }
108: 
109:   @override
110:   Widget build(BuildContext context) {
111:     return Scaffold(
112:       appBar: AppBar(title: Text(context.loc.currencyRate)),
113:       body: FutureBuilder(
114:         future: _currencyListFuture,
115:         builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
116:           final List<CurrencyModel>? data = snapshot.data;
117:           if (data == null) return const SizedBox.shrink();
118: 
119:           return FadeTransition(
120:             opacity: _fadeController.view,
121:             child: Column(
122:               children: [
123:                 Padding(
124:                   padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
125:                   child: SearchView(onChanged: _filterCurrencies),
126:                 ),
127:                 if (_hasMore)
128:                   Padding(
129:                     padding: const EdgeInsets.only(bottom: 10),
130:                     child: TextButton(
131:                       onPressed: _isLoadingMore ? null : _loadNextPage,
132:                       child: _isLoadingMore
133:                           ? const SizedBox.square(
134:                               dimension: 18,
135:                               child: CircularProgressIndicator(strokeWidth: 2),
136:                             )
137:                           : Text(
138:                               context.loc.showMore,
139:                               style: context.fonts.regular14.copyWith(color: context.colors.blueDepression),
140:                             ),
141:                     ),
142:                   ),
143:                 Expanded(
144:                   child: ValueListenableBuilder<List<CurrencyModel>>(
145:                     valueListenable: _filteredCurrenciesNotifier,
146:                     builder: (BuildContext context, List<CurrencyModel> data, _) {
147:                       return ListView.builder(
148:                         itemCount: data.length,
149:                         itemBuilder: (BuildContext context, int index) {
150:                           final CurrencyModel currency = data[index];
151: 
152:                           return Padding(
153:                             key: ValueKey(currency.id),
154:                             padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
155:                             child: CurrencyCard(model: currency),
156:                           );
157:                         },
158:                         padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
159:                       );
160:                     },
161:                   ),

